import{_ as s,o as e,c as t,ag as c}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"科学日报 · 2026-11-06（物理 · 铜氧化物赝能隙＝电子配对能量）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/physics/science-daily-2026-11-06-physics.md","filePath":"topics/physics/science-daily-2026-11-06-physics.md"}'),i={name:"topics/physics/science-daily-2026-11-06-physics.md"};function r(n,o,a,d,l,p){return e(),t("div",null,[...o[0]||(o[0]=[c('<h1 id="科学日报-·-2026-11-06-物理-·-铜氧化物赝能隙-电子配对能量" tabindex="-1">科学日报 · 2026-11-06（物理 · 铜氧化物赝能隙＝电子配对能量） <a class="header-anchor" href="#科学日报-·-2026-11-06-物理-·-铜氧化物赝能隙-电子配对能量" aria-label="Permalink to &quot;科学日报 · 2026-11-06（物理 · 铜氧化物赝能隙＝电子配对能量）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-06.md</code> — 第56期 ｜ 科学板块（物理向 1 篇） 落盘说明：文件名带 <code>-physics</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-11-06-物理-·-1-1-赝能隙不是「另一种序」-它就是配对本身" tabindex="-1">科学日报 2026-11-06（物理 · 1/1）：赝能隙不是「另一种序」，它就是配对本身 <a class="header-anchor" href="#科学日报-2026-11-06-物理-·-1-1-赝能隙不是「另一种序」-它就是配对本身" aria-label="Permalink to &quot;科学日报 2026-11-06（物理 · 1/1）：赝能隙不是「另一种序」，它就是配对本身&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-06.md</code> ｜ DOI: 10.1126/science.adt3444 ｜ Science (2026)</p></blockquote><ul><li>问题：<strong>赝能隙（pseudogap）</strong> 是铜氧化物高温超导相图里最突出的谜——它在 <strong>Tc 之上</strong>就已打开，<strong>来源</strong>与<strong>和超导的关系</strong>长期未决：一派认为来自<strong>预先形成的电子对（preformed pairs）</strong>，一派归因于<strong>电荷密度波等局域有序</strong>。判据之争的本质是「<strong>赝能隙是配对的先兆，还是另一个竞争的序</strong>」。</li><li>方法：用<strong>局域散粒噪声谱（local shot-noise spectroscopy）</strong> 在 <strong>Bi₂Sr₂CaCu₂O₈₊δ</strong> 上<strong>直接测量配对</strong>（散粒噪声对电子是否成对有直接响应），并与赝能隙能标对照。</li><li>结果（实测）： <ul><li><strong>赝能隙的能量与电子配对的起始能量重合</strong>——支持<strong>配对图景</strong>；</li><li>赝能隙<strong>空间高度非均匀</strong>，最高达 <strong>70 meV</strong>；</li><li>直接<strong>排除「赝能隙纯属局域有序」<strong>的解释；把赝能隙</strong>与库珀对形成</strong>联系起来，并提示<strong>进一步提高 Tc 的瓶颈是相位相干</strong>，而不是配对。</li></ul></li><li>洞察（对本库 <code>physics</code> × <code>materials</code>）： <ol><li><strong>「把争论落到一个可直接测的量上」</strong>——不是再争论赝能隙『像什么』，而是<strong>测配对本身</strong>，让能量尺度直接对齐；判据：<strong>当两个假说各说各话时，去找一个只被其中一方预测的可观测量</strong>。</li><li><strong>「限制性能的不是『能不能发生』，而是『相干不相干』」</strong>——配对早已发生，瓶颈在<strong>相位相干</strong>；判据：<strong>优化一个系统时，先分清『有没有（存在性）』与『连不连得起来（相干/一致性）』</strong>（呼应母题「<strong>约束-涌现</strong>」与「<strong>改路径优于加力度</strong>」）。</li><li><strong>与库内呼应</strong>：与 <code>topics/quantum-physics/science-daily-2026-11-06-quantum.md</code>（三味哈伯德量子模拟，同属<strong>强关联多体</strong>主题）同日成对；与 <code>topics/physics/index.md</code> 的凝聚态脉络一脉相承。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/physics/index.md</code> ｜ <code>topics/physics/advanced-materials-deep.md</code> ｜ 第56期 科学板块</p></blockquote><p>关键词：科学日报第56期、铜氧化物高温超导、赝能隙pseudogap、配对能量pairing energy、局域散粒噪声谱local shot-noise spectroscopy、Bi2Sr2CaCu2O8+δ、预先形成的电子对preformed pairs、电荷密度波局域有序、70meV、空间非均匀、库珀对Cooper pair、相位相干phase coherence、Tc瓶颈、把争论落到可直接测的量、存在性与相干性之分、强关联多体</p><p>关联：<code>topics/physics/index.md</code>、<code>topics/physics/science-daily-2026-11-05-physics.md</code>、<code>topics/quantum-physics/science-daily-2026-11-06-quantum.md</code>、<code>topics/materials/index.md</code>、<code>ScienceDaily/daily/2026-11-06.md</code></p>',10)])])}const m=s(i,[["render",r]]);export{h as __pageData,m as default};
